/** base64 PCM16 → -1..1 float. 호출할 때마다 새 배열을 만든다(호출한 쪽이 보관·해제). */
export function decodeGunshot(): { data: Float32Array; rate: number } {
  const bin = atob(GUNSHOT_PCM16_BASE64)
  const data = new Float32Array(bin.length >> 1)
  for (let i = 0; i < data.length; i++) {
    const v = bin.charCodeAt(i * 2) | (bin.charCodeAt(i * 2 + 1) << 8)
    data[i] = (v > 32767 ? v - 65536 : v) / 32768
  }
  return { data, rate: GUNSHOT_RATE }
}
